css:
* { box-sizing: border-box; }
html, body {
  width: 100%; height: 100%; margin: 0;
  overflow: hidden; background: transparent !important;
}
.quality-widget {
  position: relative;
  width: 100%; height: 100%;
  padding: 84px 30px 18px;
  background: transparent; color: #202f38;
  font-family: Arial, Helvetica, sans-serif;
  user-select: none; pointer-events: none;
  opacity: var(--w-opacity, 1);
}
/* Posición y tipografía comunes a las demás pantallas. */
.screen-header {
  position: absolute; top: 0; left: 0; right: 0;
  height: 76px; padding: 14px 30px 0;
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 24px;
}
.screen-heading { flex: 1; min-width: 0; }
.screen-title {
  margin: 0; padding: 0; color: #0E5B67;
  font-size: 28px; font-weight: 700; line-height: 1.05;
  white-space: nowrap;
}
.screen-subtitle {
  margin: 5px 0 0; padding: 0; color: #728DA5;
  font-size: 14px; font-weight: 400; line-height: 1.3;
  white-space: nowrap;
}
.company-logo { display: block; width: 142px; height: 61px; object-fit: contain; flex: 0 0 auto; }
.quality-layout {
  display: grid;
  grid-template-rows: 76px 76px 74px 1px 92px 84px 24px minmax(0, 1fr);
  gap: 6px; width: 100%; height: 100%; min-height: 0;
}
.quality-row { display: grid; gap: 12px; min-width: 0; min-height: 0; }
.quality-row--top { grid-template-columns: minmax(0,1.9fr) minmax(0,.72fr) minmax(0,1.05fr) minmax(0,.60fr); }
.quality-row--second { grid-template-columns: minmax(0,.85fr) minmax(0,.59fr) minmax(0,1.38fr) minmax(0,1.4fr); }
.quality-row--third { grid-template-columns: minmax(0,2.5fr) minmax(0,1fr); column-gap: 11%; }
.quality-row--middle { grid-template-columns: 110px minmax(0,1.05fr) minmax(0,1fr) 135px; }
.quality-row--lower { grid-template-columns: 200px minmax(0,.66fr) minmax(0,1fr); gap: 28px; }
.quality-panel {
  display: flex; flex-direction: column;
  min-width: 0; min-height: 0; padding: 5px 8px;
  border: 1px solid #9aadb7; border-radius: 3px;
  background: #fff;
}
.panel-title {
  display: flex; align-items: center; justify-content: center;
  flex: 0 0 auto; min-height: 18px; margin-bottom: 3px;
  color: #164d5b; font-size: 14px; font-weight: 700;
  line-height: 1.1; text-align: center;
}
.field-grid {
  display: grid; grid-template-columns: repeat(var(--columns,1), minmax(0,1fr));
  gap: 6px; align-items: end;
  width: 100%; min-width: 0; min-height: 0; flex: 1;
}
.field { display: flex; flex-direction: column; justify-content: flex-end; min-width: 0; min-height: 0; }
.field-label {
  display: flex; align-items: center; justify-content: center;
  min-height: 19px; padding: 0 1px 3px;
  color: #263740; font-size: 13px; font-weight: 600;
  line-height: 1.12; text-align: center; white-space: pre-line;
}
.field-label:empty { display: none; }
.field-slot, .result-slot, .observation-slot {
  border: 1px solid #879ca7; border-radius: 1px; background: #fff;
  color: #111; font-family: Arial, Helvetica, sans-serif;
  font-variant-numeric: tabular-nums;
}
.field-slot { width: 100%; height: 23px; flex: 0 0 auto; }
.quality-panel--dense .field-label { min-height: 32px; font-size: 12px; }
.quality-row--lower .quality-panel--dense .field-label { min-height: 28px; }
.quality-panel--centered { justify-content: center; gap: 5px; }
.quality-panel--centered .field-grid { width: min(110px,100%); flex: 0 0 auto; align-self: center; }
.quality-panel--dryer { justify-self: end; width: min(135px,100%); }
.quality-panel--dryer .field-label { min-height: 28px; }
.quality-panel--vaporizador { padding-top: 4px; padding-bottom: 4px; }
.quality-panel--vaporizador .panel-title { min-height: 16px; margin-bottom: 0; }
.quality-panel--vaporizador .field-label { min-height: 27px; padding-bottom: 2px; font-size: 11px; line-height: 1.06; }
.quality-row--lower #ensayos-fields .field-label { font-size: 11px; }
.quality-divider { width: 100%; border-top: 1px solid #c4ced4; }
.results-divider {
  display: flex; align-items: center; gap: 12px;
  color: #164d5b; font-size: 15px; font-weight: 700; white-space: nowrap;
}
.results-divider::before, .results-divider::after { content: ""; flex: 1; border-top: 1px solid #9aadb7; }
.quality-bottom { display: grid; grid-template-columns: minmax(0,.75fr) minmax(0,1fr); gap: 18px; min-height: 0; min-width: 0; }
.quality-panel--results { padding: 0; overflow: hidden; }
.results-table {
  display: grid; grid-template-columns: 30px repeat(4,minmax(0,1fr));
  grid-template-rows: 30px repeat(7,minmax(0,1fr));
  width: 100%; height: 100%; min-width: 0; min-height: 0;
}
.result-heading, .result-number, .result-slot {
  display: flex; align-items: center; justify-content: center;
  width: 100%; height: 100%; min-width: 0; min-height: 0;
  border: 0; border-right: 1px solid #b5c2c9; border-bottom: 1px solid #b5c2c9;
  border-radius: 0;
}
.result-heading { background: #edf2f4; color: #20343e; font-size: 12px; font-weight: 700; line-height: 1.1; text-align: center; }
.result-number { background: #f5f7f8; font-size: 13px; font-weight: 700; }
.results-table > :nth-child(5n) { border-right: 0; }
.results-table > :nth-last-child(-n+5) { border-bottom: 0; }
.quality-side { display: grid; grid-template-columns: minmax(0,1.45fr) minmax(0,1fr); grid-template-rows: 50px 52px minmax(0,1fr); gap: 8px; min-width: 0; min-height: 0; }
.quality-panel--summary { grid-column: 1; grid-row: 1; }
.quality-panel--registry { grid-column: 2; grid-row: 1; }
.quality-panel--humidity { grid-column: 1; grid-row: 2; }
.quality-panel--observations { grid-column: 2; grid-row: 2 / 4; }
.quality-panel--humidity { padding: 2px 5px; }
.quality-panel--humidity .panel-title { min-height: 9px; margin-bottom: 0; font-size: 10px; }
.quality-panel--humidity .field-label { min-height: 20px; padding: 0; font-size: 10px; line-height: 1; }
.quality-panel--humidity .field-slot { height: 18px; }
.quality-panel--registry { padding: 4px 8px; }
.quality-panel--observations .panel-title { justify-content: flex-start; }
.observation-slot { width: 100%; min-height: 0; flex: 1; margin-top: 3px; }
/* Impresión del documento del widget: una página A4 horizontal.
 * La impresión de la pantalla externa depende de PSI CORE.
 */
@page { size: A4 landscape; margin: 10mm; }
@media print {
  html, body { width: auto; height: auto; overflow: visible; background: #fff !important; }
  .quality-widget {
    width: 277mm; height: 189mm; padding: 19mm 0 0;
    background: #fff; color: #000; opacity: 1;
    break-inside: avoid; page-break-inside: avoid;
    -webkit-print-color-adjust: exact; print-color-adjust: exact;
  }
  .screen-header { height: 17mm; padding: 0; gap: 5mm; }
  .screen-title { font-size: 16pt !important; color: #000; }
  .screen-subtitle { margin-top: 1.5mm; font-size: 9pt !important; color: #333; }
  .company-logo { width: 37mm; height: 16mm; }
  .quality-layout { grid-template-rows: 19mm 19mm 17mm .3mm 23mm 20mm 7mm minmax(0,1fr); gap: 1.5mm; }
  .quality-row { gap: 2mm; }
  .quality-row--third { grid-template-columns: minmax(0,2.5fr) minmax(0,1fr); column-gap: 11%; }
  .quality-row--middle { grid-template-columns: 20mm minmax(0,1.05fr) minmax(0,1fr) 25mm; }
  .quality-row--lower { grid-template-columns: 36mm minmax(0,.66fr) minmax(0,1fr); gap: 3mm; }
  .quality-panel { padding: 1.2mm 1.5mm; border: .2mm solid #777; border-radius: 0; box-shadow: none; break-inside: avoid; }
  .panel-title { font-size: 8.5pt; min-height: 3.5mm; margin-bottom: .7mm; color: #111; }
  .field-grid { gap: 1mm; }
  .field-label { min-height: 4mm; padding: 0 .2mm .6mm; font-size: 7.5pt; color: #111; }
  .quality-panel--dense .field-label { min-height: 8mm; font-size: 7.3pt; }
  #ensayos-fields .field:nth-child(2) .field-label { font-size: 6.7pt; }
  .field-slot { height: 5.5mm; }
  .quality-panel--dryer { width: 25mm; }
  .quality-panel--dryer .field-label { min-height: 7mm; }
  .quality-panel--centered { gap: 1mm; }
  .quality-panel--centered .field-grid { width: min(22mm,100%); }
  .results-divider { color: #111; font-size: 9pt; gap: 2mm; }
  .quality-bottom { grid-template-columns: minmax(0,.75fr) minmax(0,1fr); gap: 3mm; }
  .quality-panel--results { padding: 0; }
  .results-table { grid-template-columns: 6mm repeat(4,minmax(0,1fr)); grid-template-rows: 8mm repeat(7,minmax(0,1fr)); }
  .result-heading { font-size: 7.5pt; color: #111; }
  .result-number { font-size: 8pt; }
  .field-slot, .observation-slot { border-color: #777; }
  .quality-side { grid-template-rows: 12mm 13mm minmax(0,1fr); gap: 2mm; }
  .observation-slot { margin-top: 1mm; }
}

