"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 4 / CONTROL DE CALIDAD";
  const DEFAULT_SUBTITLE = "Cinta continua · Parámetros de proceso y resultados de los ensayos";

  let headerTitle = null;
  let headerSubtitle = null;

  /* NOMBRE: Título//Subtítulo. Con Título// se oculta el subtítulo.
   * Sin NOMBRE se muestran ambos textos predeterminados.
   * Sin separador se personaliza solo el título.
   */
  function updateHeader(widget) {
    if (!headerTitle || !headerSubtitle) return;
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim() : "";
    const separator = name.indexOf("//");
    const titleText = separator >= 0 ? name.slice(0, separator).trim() : name;
    const subtitleText = separator >= 0
      ? name.slice(separator + 2).trim() : DEFAULT_SUBTITLE;

    headerTitle.textContent = titleText || DEFAULT_TITLE;
    headerSubtitle.textContent = subtitleText;
    headerSubtitle.hidden = subtitleText === "";
    fitHeader();
  }

  function fitHeader() {
    [[headerTitle, 28], [headerSubtitle, 14]].forEach(function (entry) {
      const element = entry[0];
      if (!element || element.hidden) return;
      const size = entry[1];
      element.style.fontSize = size + "px";
      const available = element.clientWidth;
      if (available > 0 && element.scrollWidth > available) {
        element.style.fontSize = (size * available / element.scrollWidth) + "px";
      }
    });
  }

  let latestWidget = null;
  let headerObserver = null;




  const FIELD_GROUPS = [
    { id: "general-fields", labels: [
      "PARTIDA", "CÓDIGO", "TACHOS\n× BANDA", "MÁQUINA\nDE HILAR", "TOBERA", "RPM"
    ] },
    { id: "hilanderia-fields", labels: ["DE", "A"] },
    { id: "tachos-fields", labels: ["SF", "CI", "X", "CG"] },
    { id: "paradas-fields", labels: ["01", "OTROS"] },
    { id: "estiramiento-fields", labels: ["Pre-Estiramiento", "Principal", "Total"] },
    { id: "preparacion-superior-fields", labels: ["Tipo", "Concent."] },
    { id: "zonas-fields", labels: ["1", "2", "3", "4", "5"] },
    { id: "vapor-superior-fields", labels: ["VAPOR\nZ-1", "VAPOR\nZ-2", "TEMPERATURA\nZ-1", "TEMPERATURA\nZ-2", "TEMPERATURA\nZ-3"] },
    { id: "cortadoras-fields", labels: ["1", "2", "3", "4", "5", "6", "7", "8", "Presión", "Pesos N°"] },
    { id: "rizadoras-fields", labels: ["Rizado", "Rodillos", "Vapor", "Calef."] },
    { id: "carga-fields", labels: [""] },
    { id: "lavado-fields", labels: [
      "Estir. Rod 9\nm/min", "P. Rod.\nGoma 1", "P. Rod.\nGoma 2",
      "Ancho\nBanda (cm)", "DMF\nCuba Entrada", "DMF\nCuba Salida"
    ] },
    { id: "preparacion-fields", labels: [
      "Bomba\nDosificadora", "Agua\nAgregada", "Preparación\nAgregada",
      "Nivel\nSótano %", "Flujo\nDosif. l/min"
    ] },
    { id: "secador-fields", labels: ["Vent. Aire\nSalida"] },
    { id: "rizadora-inferior-fields", labels: ["Faja\nTransport.", "Tambor\nEnfriador"] },
    { id: "vapor-temperaturas-fields", labels: ["Cinta\nm/min", "VENTANA 1", "VENTANA 2", "VENTANA 3", "VENTANA 4"] },
    { id: "ensayos-fields", labels: [
      "Peso\nx m", "Encogim.", "Prueba\nN°", "Fardo", "Humedad\nB-2",
      "Humedad\nB-4", "DMF", "Grasa", "Título\nCorte"
    ] },
    { id: "resultados-breves-fields", labels: ["Grasa", "Título", "Corte", "Resist.", "Alarg."] },
    { id: "registro-fields", labels: ["Carga", "Fecha", "Hora"] },
    { id: "humedad-fields", labels: ["Prueba N°", "Fardo", "Humedad\nB-2", "Humedad\nB-4", "Humedad", "DMF"] }
  ];

  const RESULT_HEADINGS = [
    "PESO POR METRO", "ENCOGIMIENTO", "ENCOGIMIENTO AL AGUA", "ENCOGIMIENTO RESTANTE"
  ];

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function buildFields(config) {
    const grid = document.getElementById(config.id);
    if (!grid) return;

    grid.replaceChildren();
    grid.style.setProperty(
      "--columns",
      String(config.labels.length)
    );

    config.labels.forEach(function (label) {
      const field = make("div", "field", grid);

      make(
        "div",
        "field-label",
        field,
        label
      );

      const slot = make(
        "div",
        "field-slot",
        field
      );

      slot.setAttribute("aria-hidden", "true");
    });
  }

  function buildResults() {
    const table = document.getElementById(
      "results-table"
    );

    if (!table) return;

    table.replaceChildren();

    make("div", "result-heading", table);

    RESULT_HEADINGS.forEach(function (heading) {
      make(
        "div",
        "result-heading",
        table,
        heading
      );
    });

    for (let row = 1; row <= 7; row += 1) {
      make(
        "div",
        "result-number",
        table,
        String(row)
      );

      for (
        let column = 0;
        column < RESULT_HEADINGS.length;
        column += 1
      ) {
        const slot = make(
          "div",
          "result-slot",
          table
        );

        slot.setAttribute("aria-hidden", "true");
      }
    }
  }

  function buildWidget() {
    FIELD_GROUPS.forEach(buildFields);
    buildResults();
    headerTitle = document.querySelector(".screen-title");
    headerSubtitle = document.querySelector(".screen-subtitle");
    updateHeader(latestWidget || window.WIDGET || null);
    if (typeof ResizeObserver !== "undefined") {
      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(document.querySelector(".screen-heading"));
    } else {
      window.addEventListener("resize", fitHeader);
    }
  }

  /* Widget visual: no recibe variables del PLC. */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
